#!/usr/bin/env python3
"""Qualify only original groupSetLodValues post-trick/file/default precedence."""
import argparse,ctypes as C,hashlib,json,os,random,tempfile
from pathlib import Path
from check_group_bounds import run
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[2]
class State(C.Structure):_fields_=[(x,C.c_float) for x in ['near_distance','near_fade','far_distance','far_fade','scale','shadow_distance']]+[(x,C.c_uint32) for x in ['from_file','from_trick','autogenerated']]
class Input(C.Structure):_fields_=[('prior',State),('file_far',C.c_float),('file_far_fade',C.c_float),('file_scale',C.c_float),('model_present',C.c_uint32),('model_min',C.c_float*3),('model_max',C.c_float*3)]
def main():
    p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);p.add_argument('--sanitize',action='store_true');a=p.parse_args()
    paths=['upstream/ouroboros/Common/group/groupfileload.c','upstream/ouroboros/libs/UtilitiesLib/include/utilitieslib/utils/mathutil.h']
    texts=[(ROOT/x).read_text().replace('\r\n','\n') for x in paths];pins={x:hashlib.sha256(t.encode()).hexdigest() for x,t in zip(paths,texts)}
    if pins!=json.loads((HERE/'lod-source-pins.json').read_text()):raise ValueError('source pin mismatch')
    start=texts[0].index('void groupSetLodValues(GroupDef *def)');end=texts[0].index('\nstatic void addLod',start)
    body=texts[0][start:end]
    code=(HERE/'tests/lod_oracle_shim.h').read_text()+body+'''
void original(const CohGroupLodInput*in,CohGroupLodState*out) {
 GroupDef d={0};Model m;d.lod_near=in->prior.near_distance;d.lod_nearfade=in->prior.near_fade;d.lod_far=in->prior.far_distance;d.lod_farfade=in->prior.far_fade;d.lod_scale=in->prior.scale;d.shadow_dist=in->prior.shadow_distance;
 d.lod_fromfile=in->prior.from_file;d.lod_fromtrick=in->prior.from_trick;d.lod_autogen=in->prior.autogenerated;
 d.from_file.lod_far=in->file_far;d.from_file.lod_farfade=in->file_far_fade;d.from_file.lod_scale=in->file_scale;
 memcpy(m.min,in->model_min,sizeof(Vec3));memcpy(m.max,in->model_max,sizeof(Vec3));d.model=in->model_present?&m:0;groupSetLodValues(&d);
 out->near_distance=d.lod_near;out->near_fade=d.lod_nearfade;out->far_distance=d.lod_far;out->far_fade=d.lod_farfade;out->scale=d.lod_scale;out->shadow_distance=d.shadow_dist;out->from_file=d.lod_fromfile;out->from_trick=d.lod_fromtrick;out->autogenerated=d.lod_autogen;
}
'''
    with tempfile.TemporaryDirectory(prefix='coh-lod-') as temp:
        d=Path(temp);(d/'original.c').write_text(code)
        run(['cc','-std=c99','-O0','-ffp-contract=off','-shared','-fPIC','-I'+str(HERE),d/'original.c','-lm','-o',d/'original.so'])
        lib=C.CDLL(str(d/'original.so'));lib.original.argtypes=[C.POINTER(Input),C.POINTER(State)];rng=random.Random(40225);fixtures=[]
        def f(v):return float(v).hex()+'f'
        def state(v):return '{'+','.join([f(getattr(v,k)) for k,_ in State._fields_[:6]]+[str(getattr(v,k)) for k,_ in State._fields_[6:]])+'}'
        def vec(v):return '{'+','.join(f(x) for x in v)+'}'
        for i in range(4096):
            inp=Input();inp.prior=State(*[rng.choice([0,0,-5,.25,1,10,100,1000]) for _ in range(6)],i&1,(i>>1)&1,(i>>2)&1)
            inp.model_present=(i>>3)&1;inp.file_far=rng.choice([0,-10,100,500]);inp.file_far_fade=rng.choice([0,.25,100]);inp.file_scale=rng.choice([0,.25,1,10])
            for j in range(3):inp.model_min[j]=rng.randint(-100,0);inp.model_max[j]=rng.randint(0,100)
            out=State();lib.original(C.byref(inp),C.byref(out))
            fixtures.append('{{'+','.join([state(inp.prior),f(inp.file_far),f(inp.file_far_fade),f(inp.file_scale),str(inp.model_present),vec(inp.model_min),vec(inp.model_max)])+'},'+state(out)+'}')
        (d/'lod_fixtures.h').write_text('static const LodFixture fixtures[]={'+',\n'.join(fixtures)+'};\n')
        sources=[HERE/'coh_group_lod.c',HERE/'tests/test_group_lod.c'];checks={}
        for mode,flags in [('release',['-O2'])]+([('asan',['-O1','-g','-fsanitize=address','-fno-omit-frame-pointer','-no-pie']),('ubsan',['-O1','-g','-fsanitize=undefined','-fno-sanitize-recover=all'])] if a.sanitize else []):
            binary=d/mode;run(['cc','-std=c99','-Wall','-Wextra','-Werror','-ffp-contract=off',*flags,'-I'+str(HERE),'-I'+str(d),*sources,'-lm','-o',binary]);checks[mode]=json.loads(run([binary],env=dict(os.environ,ASAN_OPTIONS='detect_leaks=0:halt_on_error=1',UBSAN_OPTIONS='halt_on_error=1')))
        result={'passed':True,'checks':checks,'fixtures':len(fixtures),'original_source_sha256_lf':pins,'original_function_sha256':hashlib.sha256(body.encode()).hexdigest(),'oracle_sha256':hashlib.sha256(code.encode()).hexdigest(),'source_oracle_sanitized':False,'leak_sanitizer':False,'source_sha256':{str(x.relative_to(ROOT)):hashlib.sha256(x.read_bytes()).hexdigest() for x in [*sources,HERE/'coh_group_lod.h',HERE/'tests/lod_oracle_shim.h',Path(__file__),HERE/'check_group_bounds.py']},'client_trick_model_lod_info_admitted':False,'world_renderer_authority':False,'android_execution':False}
        a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result))
if __name__=='__main__':main()
